import{c as d,$ as o,Q as i,j as l,g as e,n as s,o as t,m as c}from"./chunks/framework.CWBTDBPu.js";const b=JSON.parse('{"title":"YuPay 常见问题","description":"","frontmatter":{"title":"YuPay 常见问题"},"headers":[],"relativePath":"plugins/items/yupay/faq.md","filePath":"plugins/items/yupay/faq.md"}'),p={name:"plugins/items/yupay/faq.md"},u={class:"quick-actions"};function h(y,a,_,f,m,P){const r=o("CopyMarkdownButton"),n=o("CopyLLMButton");return i(),l("div",null,[a[0]||(a[0]=e("h1",{id:"yupay-常见问题",tabindex:"-1"},[s("YuPay 常见问题 "),e("a",{class:"header-anchor",href:"#yupay-常见问题","aria-label":'Permalink to "YuPay 常见问题"'},"​")],-1)),e("div",u,[t(r,{page:""}),t(n,{page:""})]),a[1]||(a[1]=c('<h2 id="为什么强调无中间商" tabindex="-1">为什么强调无中间商？ <a class="header-anchor" href="#为什么强调无中间商" aria-label="Permalink to &quot;为什么强调无中间商？&quot;">​</a></h2><p>YuPay 的设计是服主直接对接自己的微信支付、支付宝官方商户号。资金不经过第三方代收平台，插件只负责在服务器内创建订单、处理回调、发放奖励和记录数据。</p><h2 id="费率是多少" tabindex="-1">费率是多少？ <a class="header-anchor" href="#费率是多少" aria-label="Permalink to &quot;费率是多少？&quot;">​</a></h2><p>常见官方通道费率为 <code>0.2%-0.6%</code>。如果你需要永久 <code>0.2%</code> 费率，请联系作者处理商户通道方案。</p><h2 id="支付成功但没有发奖励怎么办" tabindex="-1">支付成功但没有发奖励怎么办？ <a class="header-anchor" href="#支付成功但没有发奖励怎么办" aria-label="Permalink to &quot;支付成功但没有发奖励怎么办？&quot;">​</a></h2><p>先执行 <code>/yp health</code> 检查支付渠道、数据库和依赖状态，再查看订单历史与奖励日志。若奖励命令依赖 Vault、PlayerPoints 或跨服队列，请确认对应软依赖已正常加载。</p><h2 id="回调失败怎么排查" tabindex="-1">回调失败怎么排查？ <a class="header-anchor" href="#回调失败怎么排查" aria-label="Permalink to &quot;回调失败怎么排查？&quot;">​</a></h2><p>确认 <code>notify-url</code> 使用公网可访问的 HTTP/HTTPS 地址，服务器防火墙已放行端口，反向代理没有拦截支付平台 POST 请求。微信支付还需要确认 API v3 密钥、商户私钥、平台公钥和证书序列号匹配。</p><h2 id="退款需要管理员审核吗" tabindex="-1">退款需要管理员审核吗？ <a class="header-anchor" href="#退款需要管理员审核吗" aria-label="Permalink to &quot;退款需要管理员审核吗？&quot;">​</a></h2><p>玩家可提交退款申请，管理员可以通过 <code>/yp refund approve &lt;请求ID&gt;</code> 或 <code>/yp refund reject &lt;请求ID&gt;</code> 审核；也可以使用带 <code>-f</code> 的直接退款命令处理特殊情况。</p><h2 id="可以给其他插件调用吗" tabindex="-1">可以给其他插件调用吗？ <a class="header-anchor" href="#可以给其他插件调用吗" aria-label="Permalink to &quot;可以给其他插件调用吗？&quot;">​</a></h2><p>可以。建议在 <code>api.allowed-plugins</code> 中按插件名授权，只给可信插件开放创建订单、取消订单和查询订单等必要能力；退款与绕过奖励能力默认保持关闭。</p>',12))])}const k=d(p,[["render",h]]);export{b as __pageData,k as default};
